//! Test streams for the JPEG XL DNG tests: bare codestreams written by libjxl 0.11.1 (`cjxl <in> <out> -d <0|1> -e 7`)
//! from the synthetic images below, with the container boxes stripped. Our own output of our own images; no
//! third-party content. Regenerate with the same formulas if a decoder change ever needs different streams.
//!
//! `val` is the sample pattern of the lossless images (16×16; `maxv` is 65535, 4095 and 1023):
//! `((x*37 + y*91 + c*1013 + x*y*7) * 131) % (maxv + 1)`. `LOSSY` is `8000 + x*1100 + y*400 + c*5000` (16-bit);
//! `FLOAT` is `(x+1)*0.125 + y*0.015625 + c*0.0625`.
#![allow(dead_code)]

pub fn val(x: usize, y: usize, c: usize, maxv: u32) -> u32 {
    (((x * 37 + y * 91 + c * 1013 + x * y * 7) * 131) % (maxv as usize + 1)) as u32
}

